        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return v.get("x"), v.get("y")
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def in_bounds(p):
        return p is not None and (w <= 0 or (0 <= p[0] < w)) and (h <= 0 or (0 <= p[1] < h))

    def nearest(items, src):
        best = None
        best_d = None
        for it in items or []:
            p = pos(it)
            if not in_bounds(p):
                continue
            d = manhattan(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest(items, src):
        best = None
        best_d = None
        for it in items or []:
            p = pos(it)
            if not in_bounds(p):
                continue
            d = manhattan(src, p)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "") or ""
    role = observation.get("self_role", "") or ""
    self_pos = pos(observation.get("self_position")) or pos(observation.get("agent_position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position")) or pos(observation.get("enemy_position")) or self_pos
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    resources = observation.get("resources") or observation.get("resource_cells") or observation.get("resource_positions") or []
    unclaimed = observation.get("unclaimed_cells") or observation.get("frontier") or observation.get("neutral_cells") or []
    opp_terr = observation.get("opponent_territory") or observation.get("enemy_territory") or []
    own_terr = observation.get("self_territory") or observation.get("territory") or []

    if env == "pursuit_evasion":
        if role == "evader":
            corners = []
            if w > 0 and h > 0:
                corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
            target = farthest(corners, opp_pos) if corners else None
            if target is not None:
                return step_toward(self_pos, target)
            return step_away(self_pos, opp_pos)
        # pursuer
        target = opp_pos
        if in_bounds(target):
            return step_toward(self_pos, target)
        return [0, 0]

    if env == "territory_control":
        target = nearest(unclaimed, self_pos)
        if target is None:
            target = nearest(opp_terr, self_pos)
        if target is None and w > 0 and h > 0:
            center = (w // 2, h // 2)
            target = center
        if target is not None:
            move = step_toward(self_pos, target)
            if own_terr and manhattan(self_pos, target) <= 1:
