                if abs(away[0]) + abs(away[1]) > abs(move[0]) + abs(move[1]):
                    return away
            return move
        return step_away(self_pos, opp_pos)

    # resource_collection or unknown
    target = nearest(resources, self_pos)
    if target is not None:
        # If opponent is closer to the same resource, try to contest by moving toward it anyway;
        # if adjacent to opponent, sidestep away to avoid direct collision.
        if manhattan(self_pos, opp_pos) <= 1 and manhattan(self_pos, target) > 0:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

